   c : array[1..8] of integer;
   status : array[1..8] of boolean;
procedure search(i : integer);
var
   kol,r,j,min,max : integer;
begin
     if i = k then begin
        kol := 1;
        for r := 1 to n do p[r] := 0;
        for j := k downto 1 do begin
                for r := 1 to n do
                p[r] := p[r] + a[r][c[j]]*kol;
            kol := kol*10;
        end;
        min := high(min);
        max := low(max);
        for r := 1 to n do begin
            if p[r] > max then max := p[r];
            if p[r] < min then min := p[r];
        end;
        if max - min < ans then ans := max - min;
        exit;
     end;
     for j := 1 to k do begin
         if status[j] = true then continue;
         inc(i);
         c[i] := j;
         status[j] := true;
         search(i);
         status[j] := false;
         dec(i);
     end;
end;
var
   i,j : integer;
   ch : char;
begin
     readln(n,k);
     for i := 1 to n do begin
         for j := 1 to k do begin
             read(ch);
             a[i][j] := strtoint(ch);
         end;
         readln;
     end;
     ans := high(ans);
     search(0);
     write(ans);
end.

