procedure swap(var q,c:longint);
var i:longint;
    begin
    i:=q; q:=c; c:=i;
    end;

procedure qcsort(q,c:longint; var qc:array of longint);
var h,e,x:longint;
    ass:boolean;
    begin
    if q>=c then exit;
    x:=q+random(c-q+1);
    swap(qc[x],qc[q]);
    ass:=true;
    for h:=q to c do if qc[h]<>qc[q] then ass:=false;
    if ass then exit; 
    h:=q; e:=c;
    while h<e do
      begin
      if qc[h]<qc[h+1] then begin swap(qc[h+1],qc[e]); dec(e); end
      else begin swap(qc[h],qc[h+1]); inc(h); end
      end;
    qcsort(q,h-1,qc);
    qcsort(e+1,c,qc);
    end;

