program Project2;

{$APPTYPE CONSOLE}

uses
  SysUtils;

var
    s: string;
    sum, k: int64;
    
begin
    k := 0;
    sum := 0;
    while not(eof) do begin
        readln(s);
        if(s[1] = '+') then
            inc(k)
        else if(s[1] = '-') then
            dec(k)
        else
            sum := sum + k * (length(s) - pos(':', s));
    end;
    writeln(sum);
end.

program format;

{$APPTYPE CONSOLE}

uses
  SysUtils;

var
  a: array [1..10000] of string;
  mx, r, n, k, f, j, i: integer;
  b: boolean;

begin
  b := true;
  mx := 0;
  r := 0;
  while not eof do
  begin
    inc(r);
    readln(a[r]);
    if (length(a[r]) > mx) then mx := length(a[r]);
  end;
  for i := 1 to mx + 2 do write('*');
  writeln;
  for i := 1 to r do
  begin
    f := mx - length(a[i]);
    n := f div 2;
    k := f div 2;
    write('*');
    if (f mod 2 = 1) then
    begin
      if b then inc(k)
      else inc(n);
      b := not b;
    end;
    for j := 1 to n do write(' ');
    write(a[i]);
    for j := 1 to k do write(' ');
    writeln('*');
  end;
  for i := 1 to mx + 2 do write('*');
  writeln;
end.

