uses Math;
const
    inf = round(1e9);
    maxn = round(1e1) + 200;
    md = round(1e9) + 7;
type
    node = record
             val, id : longint;
           end;
    edge = record
             u, f, t, cost : longint;
           end;
var
    n, k, i, j, heap_sz, ll, rr, mid : longint;
    cost : int64;
    e : array of edge;
    g : array [1..maxn] of array of longint;
    d, phi, vert, p, p_rib : array [1..maxn] of longint;
    h : array [1..maxn] of node;
    c : array [1..maxn, 1..maxn] of longint;

  procedure AddEdge(a, b, cap, cost : longint);
  var
     cur : edge;
  begin
    cur.u := cap; cur.f := 0; cur.t := b; cur.cost := cost;
    setlength(e, length(e) + 1);
    e[length(e) - 1] := cur;
    setlength(g[a], length(g[a]) + 1);
    g[a][length(g[a]) - 1] := length(e) - 1;

    cur.u := 0; cur.f := 0; cur.t := a; cur.cost := -cost;
    setlength(e, length(e) + 1);
    e[length(e) - 1] := cur;
    setlength(g[b], length(g[b]) + 1);
    g[b][length(g[b]) - 1] := length(e) - 1;
  end;

  procedure heapify(v : longint);
  var
    l, r, lowest : longint;
    t : node;
  begin
    l := v shl 1;
    r := v shl 1 + 1;
    if (l <= heap_sz) and (h[l].val < h[v].val) then lowest := l
                                                else lowest := v;
    if (r <= heap_sz) and (h[r].val < h[lowest].val) then lowest := r;
    if lowest <> v then
    begin
      vert[h[lowest].id] := v;
      vert[h[v].id] := lowest;
      t := h[v]; h[v] := h[lowest]; h[lowest] := t;
      heapify(lowest);
    end;
  end;

  procedure build_heap();
  var
     i : longint;
  begin
    heap_sz := n;
    for i := n shr 1 downto 1 do heapify(i);
  end;

  function extract_min() : longint;
  begin
    extract_min := h[1].id;
    h[1] := h[heap_sz];
    vert[h[heap_sz].id] := 1;
    dec(heap_sz);
    heapify(1);
  end;

  procedure decrease_key(v, x : longint);
  var
     t : node;
  begin
    h[v].val := x;
    while (v > 1) and (h[v shr 1].val > h[v].val) do
    begin
      vert[h[v].id] := v shr 1;
      vert[h[v shr 1].id] := v;
      t := h[v]; h[v] := h[v shr 1]; h[v shr 1] := t;
      v := v shr 1;
    end;
  end;

  procedure dijkstra(ss : longint);
  var
     v, i, id, w, t : longint;
  begin
    for i := 1 to n do
    begin
      d[i] := inf;
      vert[i] := i;
      h[i].val := inf;
      h[i].id := i;
    end;
    h[ss].val := 0;
    d[ss] := 0;
    build_heap();
    while heap_sz > 0 do
    begin
      v := extract_min();
      if d[v] = inf then break;
      for i := 0 to length(g[v]) - 1 do
      begin
        id := g[v][i];
        t := e[id].t;
        w := d[v] + e[id].cost + phi[v] - phi[t];
        if (w < d[t]) and (e[id].u - e[id].f > 0) then
        begin
          d[t] := w;
          p[t] := v;
          p_rib[t] := i;
          Decrease_Key(vert[t], d[t]);
        end;
      end;
    end;
  end;

  procedure FB(ss : longint);
  var
    i, j, r, id : longint;
    any : boolean;
  begin
    for i := 1 to n do d[i] := inf;
    d[ss] := 0;
    for i := 1 to n - 1 do
    begin
      any := false;
      for j := 1 to n do
        for r := 0 to length(g[j]) - 1 do
        begin
          id := g[j][r];
          if (e[id].u - e[id].f > 0) and (d[e[id].t] > d[j] + e[id].cost) then
          begin
            d[e[id].t] := d[j] + e[id].cost;
            any := true;
          end;
        end;
      if not any then break;
    end;

    for i := 1 to n do phi[i] := d[i];
  end;

  function mcmf(ss, tt, want : longint) : int64;
  var
     i, v, pv, pr, id : longint;
     maxflow, addflow, cost : int64;
  begin
    maxflow := 0;
    cost := 0;
    FB(ss);
    while maxflow < want do
    begin
      dijkstra(ss);
      if d[tt] = inf then break;
      for i := 1 to n do
      if d[i] < inf then phi[i] := phi[i] + d[i];

      addflow := want - maxflow;
      v := tt;
      while v <> ss do
      begin
        pv := p[v];
        pr := p_rib[v];
        id := g[pv][pr];
        addflow := min(addflow, e[id].u - e[id].f);
        v := pv;
      end;

      v := tt;
      while v <> ss do
      begin
        pv := p[v];
        pr := p_rib[v];
        id := g[pv][pr];
        e[id].f := e[id].f + addflow;
        e[id xor 1].f := e[id xor 1].f - addflow;
        cost := cost + int64(addflow) * e[id].cost;
        v := pv;
      end;

      maxflow := maxflow + addflow;
    end;

   if maxflow < want then mcmf := inf
                     else mcmf := cost;
  end;

begin
  //assign(input,'input.txt'); reset(input);
  //assign(output,'output.txt'); rewrite(output);
  randomize;
  readln(n, k);
  for i := 1 to n do
  begin
    for j := 1 to n do read(c[i][j]);
    readln;
  end;

  ll := 0;
  rr := 51 * round(1e6);
  while ll < rr do
  begin
    mid := (ll + rr) shr 1;
    for i := 1 to n do setlength(g[i], 0);
    setlength(e, 0);
    for i := 1 to n do
      for j := 1 to n do
      if c[i][j] > 0 then
      begin
        AddEdge(i, j, c[i][j], 0);
        AddEdge(i, j, inf, 1);
      end;
    cost := mcmf(1, n, mid);
    if cost <= k then ll := mid + 1
                 else rr := mid;
  end;
  setlength(e, 0);
  for i := 1 to n do
    for j := 1 to n do
    if c[i][j] > 0 then
    begin
      AddEdge(i, j, c[i][j], 0);
      AddEdge(i, j, inf, 1);
    end;
  cost := mcmf(1, n, ll);
  if cost > k then dec(ll);

  writeln(ll);
end.

const w:array[1..3]of int64=(1,1,0);
      z:array[1..3]of int64=(-1,0,1);
var n,m,x,i,j,k,l,t,o:longint;
    f:array[0..999,0..999]of int64;
begin
  f[0,0]:=1;
  read(n,m,x);
  if m<n then
    begin
      write(0);
      halt
    end;
  for i:=1to m do
    begin
      if i<n then t:=i
      else t:=n;
      for j:=t downto 0do
        for k:=t-j downto 0do
          if f[j,k]>0then
            begin
              inc(f[j+1,k],f[j,k]);
              inc(f[j,k+1],f[j,k]);
              if x=i then f[j,k]:=0
              else if k>0then inc(f[j+1,k-1],f[j,k]);
              for o:=1to 3do
                if f[j+w[o],k+z[o]]>=1000000007then dec(f[j+w[o],k+z[o]],1000000007)
            end;
    end;
  for i:=1to n do
    f[n,0]:=f[n,0]*i mod 1000000007;
  write(f[n,0])
end.

