procedure getc(var c : char);
begin
  read(c);
  while not (c in ['.', 'O']) do
    read(c);
end;

function good(a, b : integer) : boolean;
begin
  result := a and (1 shl (b - 1)) > 0;
end;

function add(a, b : integer) : integer;
begin
  result := a xor (1 shl (b - 1));
end;

begin
  //assign(input, 'input.txt'); reset(input);
